const HTML_ENTITIES: ReadonlyMap<string, string> = new Map([
  ['<', '&lt;'],
  ['>', '&gt;'],
  ['"', '&quot;'],
  ["'", '&#039;']
]);

export function sanitizeInput(input: string): string {
  return input.replace(/[<>"']/g, (char) => HTML_ENTITIES.get(char) ?? char);
}

